-- Randomized consistency check for the keyValuePairs text index: the index must never change query
-- results. Each mapContains* predicate is run twice over the same table — index enabled vs disabled
-- (use_skip_indexes = 0, query_plan_direct_read_from_text_index = 0 = brute-force ground truth) — and
-- the matched-row checksums must agree. Needles are scalar subqueries drawn from the data (a scalar
-- constant, so the index actually engages, and guaranteed present). Data is deterministic-random with
-- arbitrary bytes (NUL, 0x80+), duplicate keys built explicitly at the array level, key/value lengths
-- spanning the 63/64-byte trailer boundary, empty keys/values, over String and LowCardinality(String).
-- (m['key'] accessor predicates need a literal key to use the index and are covered by 04614/04615.)

DROP TABLE IF EXISTS t_s;
DROP TABLE IF EXISTS t_lc;
DROP TABLE IF EXISTS r;

CREATE TABLE t_s (id UInt64, m Map(String, String),
    INDEX idx m TYPE text(tokenizer = 'keyValuePairs') GRANULARITY 1)
    ENGINE = MergeTree ORDER BY id SETTINGS min_bytes_for_wide_part = 0, index_granularity = 8;
CREATE TABLE t_lc (id UInt64, m Map(LowCardinality(String), LowCardinality(String)),
    INDEX idx m TYPE text(tokenizer = 'keyValuePairs') GRANULARITY 1)
    ENGINE = MergeTree ORDER BY id SETTINGS min_bytes_for_wide_part = 0, index_granularity = 8;

SELECT number,
  arrayZip(
    all_keys,
    arrayMap(j -> if(cityHash64(number, j, 17) % 6 = 0, '',
                     arrayStringConcat(arrayMap(i -> char(cityHash64(number, j, i, 3) % 256),
                                                range(1 + (cityHash64(number, j, 11) % 20))))),
             range(length(all_keys)))
  )::Map(String, String) AS m
FROM (
  SELECT number, base_keys,
    arrayConcat(base_keys, arraySlice(base_keys, 1, 1 + (cityHash64(number, 5) % length(base_keys)))) AS all_keys
  FROM (
    SELECT number,
      arrayMap(k -> if(cityHash64(number, k, 13) % 6 = 0, '',
                       arrayStringConcat(arrayMap(i -> char(cityHash64(number, k, i) % 256),
                                                  range([1, 50, 63, 64, 65, 127, 200][1 + (cityHash64(number, k, 7) % 7)])))),
               range(1 + (cityHash64(number) % 4))) AS base_keys
    FROM numbers(200)
  )
);

CREATE TABLE r (q String, use_index UInt8, h UInt64) ENGINE = Memory;

-- Sanity: the index really engages for a representative (scalar-needle) probe.
SELECT 'directread_used', count() > 0 FROM (EXPLAIN actions = 1 SELECT id FROM t_s WHERE mapContainsKey(m, (SELECT DISTINCT arrayJoin(mapKeys(m)) AS x FROM t_s ORDER BY x LIMIT 1 OFFSET 0)) SETTINGS query_plan_direct_read_from_text_index = 1) WHERE explain LIKE '%__text_index_%';
SELECT 'probes_matched', (SELECT count() FROM r WHERE use_index = 1) > 0;

-- Any predicate where the index changed the matched-row set is a bug. Expect no rows.
SELECT q, sumIf(h, use_index = 1) AS with_index, sumIf(h, use_index = 0) AS without_index
FROM r GROUP BY q HAVING with_index != without_index ORDER BY q;

DROP TABLE t_s;
DROP TABLE t_lc;
DROP TABLE r;
